import{c as i,Q as e,j as a,m as t}from"./chunks/framework.DOi4mjdC.js";const u=JSON.parse('{"title":"概述","description":"","frontmatter":{},"headers":[{"level":1,"title":"概述","slug":"概述"}],"relativePath":"guide/算子实践参考/SIMD算子实现/矢量编程/概述.md","filePath":"guide/算子实践参考/SIMD算子实现/矢量编程/概述.md"}'),r={name:"guide/算子实践参考/SIMD算子实现/矢量编程/概述.md"};function o(n,l,s,d,f,h){return e(),a("div",null,[...l[0]||(l[0]=[t('<h1 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h1><p>本节将以Add算子为例，带您快速构建Ascend C矢量算子程序，并学习矢量算子开发的典型场景以及处理方式。涉及的场景包括：</p><ul><li><a href="./基础矢量算子.html">基础矢量算子</a>：开发一个简单的Add矢量算子。</li><li><a href="./TBuf的使用.html">TBuf的使用</a>：在算子计算过程中使用临时空间存储运算的中间结果。</li><li><a href="./多核-Tiling切分/多核Tiling.html">多核Tiling</a>：算子在AI处理器的多个核上运行，所有核的计算数据量相等且32字节对齐。</li><li><a href="./多核-Tiling切分/尾块Tiling.html">尾块Tiling</a>：算子在AI处理器的多个核上运行，所有核的计算数据量相等，每个核上除最后一个数据块（尾块）外，其余数据块的数据量相等，每个核都需要处理尾块数据的计算。</li><li><a href="./多核-Tiling切分/尾核Tiling.html">尾核Tiling</a>：算子在AI处理器的多个核上运行，数据无法平均分配到每个核。将所有核分为多个整核和多个尾核，整核的计算数据量相等，尾核的计算数据量相等。</li><li><a href="./多核-Tiling切分/尾核-尾块.html">尾核&amp;尾块</a>：算子在AI处理器的多个核上运行，数据无法平均分配到每个核，同时每个核内的数据无法均分，除最后一个数据块（尾块）外，其余数据块的数据量相等，每个核都需要单独处理尾块数据的计算。</li><li><a href="./DoubleBuffer场景.html">DoubleBuffer场景</a>：使能double buffer，算子中的多条流水并行执行。</li><li><a href="./Broadcast场景.html">Broadcast场景</a>：算子中两个输入的shape（形状）不相等，需要将一个输入的shape进行Broadcast（广播）后，再执行计算。</li><li><a href="./非对齐场景.html">非对齐场景</a>：更多数据非32字节对齐场景的处理方案。</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">注意</p><p>进行数据搬运和Vector计算时，对于搬运的数据长度和操作数的起始地址有如下的对齐要求：</p><ul><li>使用DataCopy接口进行数据搬运，搬运的数据长度和操作数的起始地址（Unified Buffer上）必须保证32字节对齐。</li><li>通常情况下，进行Vector计算时，操作数的起始地址必须保证32字节对齐，执行计算的基本单位为32字节。</li></ul></div>',4)])])}const m=i(r,[["render",o]]);export{u as __pageData,m as default};
